export function getTodayDate() {
  const today = new Date(); // Get the current date
  const todayDate = `${today.getDate()}/${today.getMonth() + 1}/${today.getFullYear()}`; // Format as DD/MM/YYYY
  return convertDMY2YMD(todayDate, true); // Convert to YYYY-MM-DD format
}

