    <!-- Cloud Upload Component -->
   

    <div v-if="isLoggedIn" class="top-bar">
      <span>Ver 1.13 Welcome, {{ userStore.username }}</span>
      <v-row class="selector-row" no-gutters>
        <v-col cols="12" sm="6" md="3">
          <PhoneIdSelector />
        </v-col>
        <v-col cols="12" sm="6" md="3">
          <AssigneeIdSelector />
        </v-col>
      </v-row>
      <cloudi-upload />
    </div>
 
    <!-- Sidebar -->
    <div v-if="isLoggedIn" class="sidebar" :class="{ open: sidebarOpen }">
      <ul>
        <li><a href="#" @click.prevent="navigateTo('todoList')">Todo List</a></li>
        <li><a href="#" @click.prevent="navigateTo('salesFunnel')">Sales Funnel</a></li>
        <li><a href="#" @click.prevent="navigateTo('messageCrud')">Message Maintenance</a></li>
        <li><a href="#" @click.prevent="navigateTo('listView')">List View</a></li>
        <li><a href="#" @click.prevent="navigateTo('ckEditor')">Script Editor</a></li>
        <li><a href="#" @click.prevent="navigateTo('kanban')">Kanban</a></li>
        <li><a href="#" @click.prevent="navigateTo('listCards')">List Cards</a></li>
        <li><a href="#" @click.prevent="navigateTo('listPhones')">List Phones</a></li>
        <li><a href="#" @click.prevent="navigateTo('counterDisplay')">Counter</a></li>
        <li><a href="#" @click.prevent="navigateTo('scheduler')">Scheduler</a></li>
        <li><a href="#" @click.prevent="navigateTo('performance')">Performance</a></li>
        <li><a href="#" @click.prevent="navigateTo('testcom')">testcom</a></li>
        <li><a href="#" @click.prevent="navigateTo('contactsManager')">contactsManager</a></li>
        <li><button @click="logout">Log Off</button></li>
      </ul>
    </div>

    <!-- Main Content -->
    <div class="main-content">
      <!-- Top Navbar -->
      <div class="navbar">
        <button class="hamburger" @click="toggleSidebar">☰</button>

      </div>

      <!-- Conditional Display -->
      <div v-if="isLoggedIn">
        <router-view />
      </div>
      <div v-if="!isLoggedIn">
        <h2>Login</h2>
        <div>
          <label for="username">Username:</label>
          <input id="username" v-model="username" type="text" />
        </div>
        <div>
          <label for="password">Password:</label>
          <input
            id="password"
            v-model="password"
            :type="showPassword ? 'text' : 'password'"
          />
          <button @click="showPassword = !showPassword">
            {{ showPassword ? "Hide" : "Show" }} Password
          </button>
        </div>
        <button @click="login">Login</button>
        <p v-if="loginError" class="error">{{ loginError }}</p>
      </div>
    </div>
  </div>
</template>

<script>
import CloudiUpload from './components/cloudiUpload.vue';
import { useRouter } from 'vue-router';
import { useUserStore } from '@/stores/user';
import  PhoneIdSelector  from './components/PhoneIdSelector.vue';
import  AssigneeIdSelector  from './components/AssigneeIdSelector.vue';

export default {
  name: 'App',
  components: {
    CloudiUpload,
    PhoneIdSelector,
    AssigneeIdSelector 
  },
  data() {
    return {
      username: '', // Added username to bind with input
      password: '', // Local state for password input
      loginError: '',
      showPassword: false,
      sidebarOpen: false,
      isLoggedIn: false, // Added to control login state locally
    };
  },
  setup() {
    const router = useRouter();
    const userStore = useUserStore();
    const navigateTo = (routeName) => {
      router.push({ name: routeName });
    };

    return { navigateTo, userStore };
  },
  mounted() {
    this.checkLoginState();
  },
  methods: {
    checkLoginState() {
      const storedUsername = localStorage.getItem('username');
      const storedPassword = localStorage.getItem('password');

      if (storedUsername && storedPassword) {
        this.username = storedUsername; // Set local username
        this.password = storedPassword;
        this.login(); // Validate login
      }
    },
    login() {
      const users = [
        { name: 'Alyssa', password: 'trewq' },
        { name: 'Alvin', password: 'trewq' },
        { name: 'Ashton', password: 'trewq' },
      ];

      // Use local username and password from input fields
      const user = users.find((u) => u.name === this.username);
      if (user && user.password === this.password.split('').reverse().join('')) {
        this.isLoggedIn = true;
        this.userStore.setUser(this.username); // Update Pinia store
        localStorage.setItem('username', this.username);
        localStorage.setItem('password', this.password);
        this.loginError = ''; // Clear error on success
      } else {
        this.loginError = 'Invalid username or password';
        this.isLoggedIn = false;
      }
    },
    logout() {
      this.userStore.clearUser();
      localStorage.removeItem('username');
      localStorage.removeItem('password');
      this.username = '';
      this.password = '';
      this.isLoggedIn = false;
      this.sidebarOpen = false;
    },
    toggleSidebar() {
      this.sidebarOpen = !this.sidebarOpen;
    },
  },
};
</script>

