<template>
  <div class="assignee-id-selector">
    <v-select
      v-model="selectedassigneeId"
      :items="assigneeIds"
      label="Select Default Assignee ID"
      outlined
      dense
      @update:modelValue="AssigneeIdChange"
      class="assignee-id-dropdown"
    ></v-select>
  </div>
</template>

<script>
import { defineComponent, computed, onMounted } from 'vue';
import { AssigneeIdStore } from '@/stores/user';

export default defineComponent({
  name: 'AssigneeSelector',
  setup() {
    const assigneeStore = AssigneeIdStore();
    console.log('Setup, initial defaultAssigneeId:', assigneeStore.defaultAssigneeId);

    // Use computed to bind directly to the store
    const selectedassigneeId = computed({
      get: () => assigneeStore.defaultAssigneeId,
      set: (newValue) => assigneeStore.setDefaultAssigneeId(newValue)
    });

    const assigneeIds = assigneeStore.assigneeIds;

    const AssigneeIdChange = (newassigneeId) => {
      console.log('AssigneeIdChange, new value:', newassigneeId);
      assigneeStore.setDefaultAssigneeId(newassigneeId);
    };

    onMounted(() => {
      console.log('onMounted, before check, defaultAssigneeId:', assigneeStore.defaultAssigneeId);
      console.log('onMounted, localStorage:', localStorage.getItem('defaultAssigneeId'));
      if (assigneeStore.defaultAssigneeId === null || assigneeStore.defaultAssigneeId === undefined) {
        console.log('Setting default to:', assigneeIds[0]);
        assigneeStore.setDefaultAssigneeId(assigneeIds[0]);
      }
      console.log('onMounted, after check, defaultAssigneeId:', assigneeStore.defaultAssigneeId);
    });

    return {
      selectedassigneeId,
      assigneeIds,
      AssigneeIdChange,
    };
  },
});
</script>

<style scoped>
.assignee-id-selector {
  max-width: 300px;
  margin: 16px 0;
}
.assignee-id-dropdown {
  font-size: 14px;
}
</style>