<template>
  <div v-if="visible" class="dialog-overlay">
    <div class="dialog-content">
      <h3>Data Selection</h3>

      <!-- Date Selection -->
      <div class="selection-section">
        <h4>Select Dialed Date (Optional)</h4>
        <input 
          type="date" 
          v-model="selectedDate" 
          class="date-input"
        />
      </div>

      <!-- Project Selection -->
      <div class="selection-section">
        <h4>Select Project</h4>
        <div class="project-list">
          <button 
            v-for="project in projects" 
            :key="project"
            @click="selectProject(project)"
            :class="['project-button', { 'selected': selectedProject === project }]"
          >
            {{ project }}
          </button>
        </div>
      </div>

      <!-- Rating Selection -->
      <div class="selection-section">
        <h4>Select Rating</h4>
        <div class="rating-list">
          <button 
            v-for="rating in ratings" 
            :key="rating"
            @click="selectRating(rating)"
            :class="['rating-button', { 'selected': selectedRating === rating }]"
          >
            {{ rating }}
          </button>
        </div>
      </div>

      <!-- Location Selection -->
      <div class="selection-section">
        <h4>Select Location</h4>
        <div class="location-list">
          <button 
            v-for="location in locations" 
            :key="location"
            @click="selectLocation(location)"
            :class="['location-button', { 'selected': selectedLocation === location }]"
          >
            {{ location }}
          </button>
        </div>
      </div>

      <!-- Action Buttons -->
      <div class="dialog-actions">
        <button 
          @click="handleConfirm" 
          class="confirm-button"
          :disabled="isConfirmDisabled || !selectedProject"
        >
          Confirm
        </button>
        <button @click="$emit('close')" class="cancel-button">
          Cancel
        </button>
      </div>
    </div>
  </div>
</template>

<script>
import { defineComponent, ref, watch } from 'vue';

export default defineComponent({
  name: 'ProjectSelectionDialog',
  props: {
    visible: {
      type: Boolean,
      required: true
    },
    defaultRating: {
      type: Number,
      default: 4 // Default value is null if no rating is passed
    }
  },
  emits: ['close', 'select-data'],
  setup(props, { emit }) {
    const projects = [
      'All',
      'Parklane',
      'm_terra',
      'rbj',
      'task',
      'Parklane OUG',
      'Parklane 1',
      'Parklane 2',
      'Parklane 3',
      'Parklane 4',
      'Parklane 5',
      'Eco Majestic Semenyih',
      'BUKIT OUG CONDOMINIUM',
      'TMN YARL',
      'Sutra Embun',
      'RSKU Sungai Long'
    ];

    const ratings = [0, 1, 2, 3, 4, 5, 6, 7, 8];
    const locations = [
      'All',
      'rbj',
      'parklane',
    ];

    const selectedProject = ref(null);
    const selectedRating = ref(props.defaultRating || null);
    const selectedLocation = ref('All');
    const selectedDate = ref(null); // Track selected date
    const isConfirmDisabled = ref(false); // Track button disabled state

    const selectProject = (project) => {
      selectedProject.value = project;
    };

    const selectRating = (rating) => {
      selectedRating.value = rating;
    };

    const selectLocation = (location) => {
      selectedLocation.value = location;
    };

    const handleConfirm = () => {
      if (selectedProject.value) {
        isConfirmDisabled.value = true; // Disable the button
        emit('select-data', {
          project: selectedProject.value,
          rating: selectedRating.value,
          location: selectedLocation.value,
          dialedDate: selectedDate.value // Emit selected date
        });
      }
    };

    // Watch for changes in defaultRating
    watch(
      () => props.defaultRating,
      (newDefaultRating) => {
        selectedRating.value = newDefaultRating || null;
      }
    );

    // Watch for changes in visibility
    watch(
      () => props.visible,
      (isVisible) => {
        if (isVisible) {
          // Reset selections when dialog opens
          selectedLocation.value = 'All';
        } else {
           isConfirmDisabled.value = false;
         }
      }
    );

    return {
      projects,
      ratings,
      locations,
      selectedProject,
      selectedRating,
      selectedLocation,
      selectedDate,
      isConfirmDisabled,
      selectProject,
      selectRating,
      selectLocation,
      handleConfirm
    };
  }
});
</script>

<style scoped>
.dialog-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
}

.dialog-content {
  background-color: white;
  padding: 2rem;
  border-radius: 8px;
  max-width: 600px;
  width: 90%;
  max-height: 90vh;
  overflow-y: auto;
}

.selection-section {
  margin-bottom: 1.5rem;
}

h3 {
  margin: 0 0 1.5rem 0;
  font-size: 1.5rem;
  color: #2c3e50;
}

h4 {
  margin: 0 0 1rem 0;
  font-size: 1.1rem;
  color: #2c3e50;
}

.project-list, .location-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.rating-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(60px, 1fr));
  gap: 0.75rem;
}

.project-button, .rating-button, .location-button {
  padding: 0.75rem;
  border: 1px solid #ddd;
  border-radius: 4px;
  background-color: #f8f9fa;
  cursor: pointer;
  transition: all 0.2s;
  text-align: center;
}

.project-button.selected, .rating-button.selected, .location-button.selected {
  background-color: #007bff;
  color: white;
  border-color: #0056b3;
}

.project-button:hover, .rating-button:hover, .location-button:hover {
  background-color: #e9ecef;
  border-color: #ced4da;
}

.project-button.selected:hover, .rating-button.selected:hover, .location-button.selected:hover {
  background-color: #0056b3;
}

.dialog-actions {
  display: flex;
  gap: 1rem;
  margin-top: 1.5rem;
}

.confirm-button, .cancel-button {
  flex: 1;
  padding: 0.75rem;
  border-radius: 4px;
  cursor: pointer;
  border: none;
  transition: background-color 0.2s;
}

.confirm-button {
  background-color: #28a745;
  color: white;
}

.confirm-button:hover {
  background-color: #218838;
}

.confirm-button:disabled {
  background-color: #6c757d;
  cursor: not-allowed;
}

.cancel-button {
  background-color: #dc3545;
  color: white;
}

.cancel-button:hover {
  background-color: #c82333;
}

.date-input {
  padding: 0.5rem;
  border: 1px solid #ddd;
  border-radius: 4px;
  width: 100%;
  box-sizing: border-box;
}

@media (max-width: 768px) {
  .dialog-content {
    width: 95%;
    margin: 10px;
  }

  .project-list, .location-list {
    grid-template-columns: 1fr;
  }

  .rating-list {
    grid-template-columns: repeat(4, 1fr);
  }
}
</style>