<template>
  <div class="card-info-section">

    <div class="info-with-template">
      <textarea 
        v-model="infoData" 
        placeholder="Enter additional info..." 
        class="info-textarea"
        @input="emitUpdate"
      ></textarea>
      <div class="template-selector">
        <select 
          @change="applyTemplate($event)"
          class="template-dropdown"
        >
          <option value="">info</option>
          <option 
            v-for="(template, index) in tenantProfiles" 
            :key="index" 
            :value="index"
          >
            {{ `${template[0]} - ${template[1]}` }}
          </option>
        </select>

        <select 
        @change="applyTemplate2($event)"
        class="template-dropdown"
      >
        <option value="">Example</option>
        <option 
          v-for="(template, index) in tenantProfiles" 
          :key="index" 
          :value="index"
        >
          {{ `${template[0]} - ${template[1]}` }}
        </option>
      </select>
       
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref } from 'vue'

const props = defineProps({
  info: {
    type: String,
    default: ''
  },
  tenantProfiles: {
    type: Array,
    default: () => []
  }
})

const emit = defineEmits(['update:info'])

const infoData = ref(props.info)

const applyTemplate = (event) => {
  const selectedIndex = event.target.value
  if (selectedIndex !== "" && props.tenantProfiles[selectedIndex]?.length > 2) {
    infoData.value = props.tenantProfiles[selectedIndex][2]
    event.target.value = "";
    infoData.value = infoData.value.includes(':') 
      ? infoData.value.replace(/^(.+?:).*$/gm, '$1 ') 
      : '';
    emitUpdate()
  }
}

const applyTemplate2 = (event) => {
  const selectedIndex = event.target.value
  if (selectedIndex !== "" && props.tenantProfiles[selectedIndex]?.length > 2) {
    infoData.value = props.tenantProfiles[selectedIndex][2]
    event.target.value = "";
   
    emitUpdate()
  }
}


const emitUpdate = () => {
  emit('update:info', infoData.value)
}
</script>

<style scoped>
.card-info-section {
  margin-bottom: 20px;
}

.card-info-section h4 {
  margin-bottom: 10px;
  color: #333;
}

.info-textarea {
  flex-grow: 1;
  max-width: 80%;
  height: 100px;
  padding: 10px;
  border: 1px solid #ccc;
  border-radius: 4px;
  background-color: #f8f9fa;
  resize: vertical;
}

.info-with-template {
  position: relative;
  display: flex;
  gap: 10px;
  align-items: flex-start;
}

.template-selector {
  flex: 0 0 auto;
  display: flex;
  width: 20%;
  min-width: 200px;
  gap: 10px;
  align-items: center;
}

.template-dropdown {
  padding: 8px;
  border: 1px solid #ccc;
  border-radius: 4px;
  background-color: #fff;
  min-width: 150px;
}




</style>