<template>
  <div class="phone-id-selector">
    <v-select
      v-model="selectedPhoneId"
      :items="phoneIds"
      label="Select Default Phone ID"
      outlined
      dense
      @update:modelValue="handlePhoneIdChange"
      class="phone-id-dropdown"
    ></v-select>
  </div>
</template>

<script>
import { defineComponent, ref, watch, onMounted } from 'vue'; // Import required Composition API utilities
import { PhoneIdStore } from '@/stores/user'; // Adjust the import path as needed

export default defineComponent({
  name: 'PhoneIdSelector',
  setup() {
    // Access the Pinia store
    const phoneStore = PhoneIdStore();

    // Reactive reference to the selected phone ID, synced with the store
    const selectedPhoneId = ref(phoneStore.defaultPhoneId || phoneStore.phoneIds[0]); // Default to first option if none set

    // List of available phone IDs from the store
    const phoneIds = phoneStore.phoneIds;

    // Handle phone ID selection change
    const handlePhoneIdChange = (newPhoneId) => {
      console.log('Selected Phone ID:', newPhoneId);
      phoneStore.setDefaultPhoneId(newPhoneId); // Update the store and localStorage
      selectedPhoneId.value = newPhoneId; // Ensure local state stays in sync
    };

    // Watch for external changes to the store's defaultPhoneId (e.g., from another component)
    watch(() => phoneStore.defaultPhoneId, (newValue) => {
      if (newValue !== selectedPhoneId.value) {
        selectedPhoneId.value = newValue;
      }
    });

    // Ensure the store is initialized with a default value if none exists in localStorage
    onMounted(() => {
      if (!phoneStore.defaultPhoneId && phoneIds.length > 0) {
        phoneStore.setDefaultPhoneId(phoneIds[0]); // Set first phone ID as default
        selectedPhoneId.value = phoneIds[0];
      }
      console.log('PhoneIdSelector mounted, current defaultPhoneId:', phoneStore.defaultPhoneId);
    });

    return {
      selectedPhoneId,
      phoneIds,
      handlePhoneIdChange,
    };
  },
});
</script>

<style scoped>
.phone-id-selector {
  max-width: 300px;
  margin: 16px 0;
}

.phone-id-dropdown {
  font-size: 14px;
}
</style>