<template>
  <v-dialog :model-value="modelValue" @update:modelValue="updateDialog" max-width="1800px" persistent>
    <v-btn color="primary" text @click="updateDialog(false)">Close</v-btn>
    <v-card>
      <v-card-title>
        <span class="headline">Detailed Records2 - {{ dialogTitle }}</span>
        <v-spacer></v-spacer>
        <v-btn icon @click="addNewRecord" color="green">
          <v-icon>mdi-plus</v-icon>
        </v-btn>
      </v-card-title>

      <v-card-text>
        <EditContactForm
          v-if="showEditForm && currentContact"
          :index="selectedIndex"
          :contacts="detailedRecords"
          :on-save="saveContact"
          :nextContact="nextValidContact"
          :on-cancel="cancelEdit"
          :selectedUser="selectedUser"
          :selectedPhoneId="selectedPhoneId"
          :contact="currentContact"
          :on-delete="confirmDelete"
        />

        <div v-if="!showEditForm" class="table-container">
          <table class="data-table">
            <thead>
              <tr>
                <th>
                  <input 
                    type="checkbox" 
                    @change="toggleSelectAll" 
                    :checked="areAllSelected"
                  >
                </th>
                <th v-for="header in detailHeaders" :key="header.value" @click="sortTable(header.value)">
                  {{ header.title }}
                  <span v-if="sortBy[0].key === header.value">
                    {{ sortBy[0].order === 'desc' ? '▼' : '▲' }}
                  </span>
                </th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              <tr v-for="(item, index) in sortedRecords" :key="item.id">
                <td>
                  <input 
                    type="checkbox" 
                    :checked="isSelected(item)"
                    @change="toggleSelect(item)"
                  >
                </td>
                <td>{{ item.phoneId }}</td>
                <td>
                  <button 
                    @click="editContact(item, index)" 
                    :class="{ 'highlight': isUpdatedToday(item.updatedAt) }"
                  >
                    {{ item.id }}
                  </button>
                </td>
                <td>{{ formatDate(item.updatedAt) }}</td>
                <td>{{ formatDate(item.dialedDate) }}</td>
                <td>{{ item.project }}</td>
                <td>{{ item.name }}</td>
                <td>{{ item.phoneNumber }}</td>
                <td>{{ item.language }}</td>
                <td class="multiline-text">{{ item.interaction || 'N/A' }}</td>
                <td>{{ item.status }}</td>
                <td>{{ item.assignee }}</td>
                <td>{{ item.rating }}</td>
                <td>{{ item.requestType }}</td>
                <td>
                  <button @click="editRecord(item)">Edit</button>
                  <button @click="deleteRecord(item)">Delete</button>
                </td>
              </tr>
            </tbody>
          </table>
        </div>

        <v-dialog v-model="editDialog" max-width="500px">
          <v-card>
            <v-card-title>
              <span class="headline">{{ editMode ? 'Edit' : 'Add' }} Record</span>
            </v-card-title>
            <v-card-text>
              <v-text-field v-model="editedItem.id" label="ID" :disabled="editMode" />
              <v-text-field v-model="editedItem.dialedDate" label="Dialed Date" />
              <v-text-field v-model="editedItem.project" label="Project" />
              <v-text-field v-model="editedItem.name" label="Name" />
              <v-text-field v-model="editedItem.phoneNumber" label="Phone Number" />
              <v-text-field v-model="editedItem.language" label="Language" />
              <v-textarea v-model="editedItem.interaction" label="Interaction" rows="3" auto-grow />
              <v-text-field v-model="editedItem.assignee" label="Assignee" />
              <v-text-field v-model="editedItem.rating" label="Rating" type="number" />
              <v-text-field v-model="editedItem.status" label="Status" />
              <v-text-field v-model="editedItem.requestType" label="Request Type" />
            </v-card-text>
            <v-card-actions>
              <v-spacer />
              <v-btn color="blue darken-1" text @click="closeEditDialog">Cancel</v-btn>
              <v-btn color="blue darken-1" text @click="saveRecord" :disabled="!valid">Save</v-btn>
            </v-card-actions>
          </v-card>
        </v-dialog>
      </v-card-text>

      <v-card-actions>
        <v-spacer />
        <v-btn color="red" text @click="deleteSelectedRecords" :disabled="!selectedRecords.length">
          Delete Selected
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script setup>
import { ref, computed, watch } from 'vue'
import EditContactForm from '@/components/EditContactForm.vue'

const props = defineProps({
  modelValue: Boolean,
  dialogTitle: String,
  detailedRecords: Array
})

const emit = defineEmits(['update:modelValue', 'updateRecords'])

const detailedRecordsKey = ref(0)
const selectedRecords = ref([])
const editDialog = ref(false)
const editMode = ref(false)
const valid = ref(true)
const showEditForm = ref(false)
const selectedIndex = ref(-1)
const currentContact = ref(null)
const selectedUser = ref('')
const selectedPhoneId = ref('')
const sortBy = ref([{ key: 'updatedAt', order: 'desc' }])

const defaultItem = {
  id: '',
  dialedDate: '',
  project: '',
  name: '',
  phoneNumber: '',
  language: '',
  interaction: '',
  assignee: '',
  rating: 0,
  status: '',
  requestType: ''
}

const editedItem = ref({ ...defaultItem })

const detailHeaders = [
  { title: 'Phone ID', value: 'phoneId', sortable: true },
  { title: 'Id', value: 'id', width: '30px', sortable: true },
  { title: 'Updated At', value: 'updatedAt', width: '110px', sortable: true },
  { title: 'Dialed Date', value: 'dialedDate', sortable: true },
  { title: 'Project', value: 'project', sortable: true },
  { title: 'Name', value: 'name', sortable: true },
  { title: 'Phone Number', value: 'phoneNumber', sortable: true },
  { title: 'Language', value: 'language', sortable: true },
  { title: 'Interaction', value: 'interaction', sortable: false },
  { title: 'Status', value: 'status', sortable: true },
  { title: 'Assignee', value: 'assignee', sortable: true },
  { title: 'Rating', value: 'rating', sortable: true },
  { title: 'Request Type', value: 'requestType', sortable: true }
]

const sortedRecords = computed(() => {
  let records = [...props.detailedRecords]
  
  if (sortBy.value[0].key) {
    records.sort((a, b) => {
      const valueA = a[sortBy.value[0].key]
      const valueB = b[sortBy.value[0].key]
      
      // Handle potential undefined or null values
      const comparisonA = valueA ?? ''
      const comparisonB = valueB ?? ''
      
      return sortBy.value[0].order === 'desc'
        ? (comparisonB.toString().localeCompare(comparisonA.toString()))
        : (comparisonA.toString().localeCompare(comparisonB.toString()))
    })
  }
  
  return records
})

const areAllSelected = computed(() => 
  selectedRecords.value.length === props.detailedRecords.length
)

const isSelected = (item) => 
  selectedRecords.value.some(selected => selected.id === item.id)

const toggleSelect = (item) => {
  const index = selectedRecords.value.findIndex(selected => selected.id === item.id)
  if (index !== -1) {
    selectedRecords.value.splice(index, 1)
  } else {
    selectedRecords.value.push(item)
  }
}

const toggleSelectAll = () => {
  if (areAllSelected.value) {
    selectedRecords.value = []
  } else {
    selectedRecords.value = [...props.detailedRecords]
  }
}

const updateDialog = (value) => emit('update:modelValue', value)

const addNewRecord = () => {
  editMode.value = false
  editedItem.value = { ...defaultItem }
  editDialog.value = true
}

const editRecord = (item) => {
  editMode.value = true
  editedItem.value = { ...item }
  editedItem.value.dialedDate = item.dialedDate?.split('T')[0] || ''
  editDialog.value = true
}

const saveRecord = () => {
  const updatedItem = { ...editedItem.value }
  if (editMode.value) {
    const index = props.detailedRecords.findIndex(r => r.id === updatedItem.id)
    if (index !== -1) {
      const updatedRecords = [...props.detailedRecords]
      updatedRecords[index] = updatedItem
      emit('updateRecords', updatedRecords, updatedItem)
    }
  } else {
    const newRecord = {
      ...updatedItem,
      id: Date.now().toString()
    }
    emit('updateRecords', [...props.detailedRecords, newRecord], newRecord)
  }
  editDialog.value = false
}

const deleteRecord = (item) => {
  if (confirm('Delete this record?')) {
    const updatedRecords = props.detailedRecords.filter(r => r.id !== item.id)
    emit('updateRecords', updatedRecords)
  }
}

const deleteSelectedRecords = () => {
  if (confirm(`Delete ${selectedRecords.value.length} records?`)) {
    const updatedRecords = props.detailedRecords.filter(
      r => !selectedRecords.value.some(selected => selected.id === r.id)
    )
    emit('updateRecords', updatedRecords)
    selectedRecords.value = []
  }
}

const closeEditDialog = () => {
  editDialog.value = false
  editedItem.value = { ...defaultItem }
}

const editContact = (contact, index) => {
  selectedIndex.value = index
  currentContact.value = contact
  showEditForm.value = true
}

const saveContact = (updatedContact) => {
  const updatedRecords = [...props.detailedRecords]
  updatedRecords[selectedIndex.value] = updatedContact
  emit('updateRecords', updatedRecords, updatedContact)
  showEditForm.value = false
}

const cancelEdit = () => {
  showEditForm.value = false
}

const confirmDelete = (contact) => {
  if (confirm('Are you sure you want to delete this contact?')) {
    const updatedRecords = props.detailedRecords.filter(r => r.id !== contact.id)
    emit('updateRecords', updatedRecords)
    showEditForm.value = false
  }
}

const nextValidContact = () => {
  const remaining = props.detailedRecords.slice(selectedIndex.value + 1)
  return remaining.find(r => r.status !== 'Registered')
}

const formatDate = (dateString) => 
  dateString ? dateString.split('T')[0] : 'N/A'

const isUpdatedToday = (dateString) => {
  if (!dateString) return false
  const today = new Date()
  const recordDate = new Date(dateString)
  return (
    recordDate.getDate() === today.getDate() &&
    recordDate.getMonth() === today.getMonth() &&
    recordDate.getFullYear() === today.getFullYear()
  )
}

const sortTable = (column) => {
  const currentSort = sortBy.value[0]
  if (currentSort.key === column) {
    // Toggle sort order if same column
    sortBy.value = [{ 
      key: column, 
      order: currentSort.order === 'desc' ? 'asc' : 'desc' 
    }]
  } else {
    // Set new sort column with default to descending
    sortBy.value = [{ key: column, order: 'desc' }]
  }
}

watch(() => props.detailedRecords, () => {
  detailedRecordsKey.value++
})
</script>

<style scoped>
.table-container {
  overflow-x: auto;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th, 
.data-table td {
  border: 1px solid #ddd;
  padding: 8px;
  text-align: left;
}

.data-table th {
  background-color: #f2f2f2;
  cursor: pointer;
}

.highlight {
  background-color: #ffffcc;
}

.multiline-text {
  white-space: pre-wrap;
}

.data-table button {
  margin: 0 4px;
}
</style>