export function updateNoteMutation(note) {
  return {
    mutation: gql`
      mutation UpdateNote($id: ID!, $input: NoteInput!) {
        updateNote(id: $id, data: $input) {
          data {
            id
            attributes {
              title
              content
              language
              requestType
            }
          }
        }
      }
    `,
    variables: {
      id: note.id,
      input: {
        title: note.title,
        content: note.content,
        language: note.language,
        requestType: note.requestType
      }
    }
  };
}

