export const MESSAGE_TEMPLATES_QUERY = gql`
 query MessageTemplates {
  messages(pagination: { limit: 1000 }, sort: ["title"]) {
    data {
      id
      attributes {
        title
        message
        category
        createdAt
        updatedAt
      }
    }
  }
}
`

export async function fetchMessageTemplates() {
  try {
    const { data } = await client.query({
      query: MESSAGE_TEMPLATES_QUERY,
      fetchPolicy: 'network-only'
    })

    return data.messages.data.map(msg => ({
      id: msg.id,
      title: msg.attributes.title,
      message: msg.attributes.message,
      category: msg.attributes.category
    }))
  } catch (error) {
    console.error('Error fetching message templates:', error)
    throw error
  }
}

