function getCardColor(requestType) {
  switch (requestType) {
    case "buyer":
      return "#A7F9CE"; // Background color for 'buyer'
    case "seller":
      return "#E9ACEF"; // Background color for 'seller'
    case "rent":
      return "#F1948A"; // Background color for 'rent'
    case "lease":
      return "#A2D9CE"; // Background color for 'lease'
    default:
      return "#D3D3D3"; // Default background color
  }
}

function getStageEmoji(Stage) {
  switch (Stage) {
    case "Qualify":
      return "🥈"; // Background color for 'buyer'
    case "Follow_up":
      return "📞";
    case "Collect":
      return "📥";
    case "Marketing":
      return "📢";
    case "Share":
      return "🎁";
    case "Schedule":
      return "📅";
    case "Closing":
      return "🏁";

    default:
      return Stage; // Default background color
  }
}



export function formatDateForStrapi(date, includeTime = false) {
  if (!date || date === '') return null;

  // Log the raw input for debugging purposes
  console.log('Raw Input:', JSON.stringify(date));

  let parsedDate;

  if (typeof date === 'string') {
    const dmyMatch = date.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (dmyMatch) {
      // Handle DD/MM/YYYY format
      const [_, day, month, year] = dmyMatch;
      parsedDate = new Date(Date.UTC(Number(year), Number(month) - 1, Number(day)));
    } else {
      // Clean the date string
      const cleanedDate = date
        .replace(/\s*\(.*?\)$/, '') // Remove parentheses and their content (e.g., "(Malaysia Time)")
        .replace(/GMT([+-]\d{2})(\d{2})/, 'GMT$1:$2'); // Add colon in offset (e.g., "GMT+0800" → "GMT+08:00")

      console.log('Cleaned Date:', cleanedDate);

      // First try standard parsing
      parsedDate = new Date(cleanedDate);
      console.log('Parsed Date (Standard):', parsedDate);

      // If still invalid, attempt manual parsing for "Mon Mar 24 2025..." format
      if (isNaN(parsedDate.getTime())) {
        const manualParseMatch = cleanedDate.match(
          /^(\w{3}) (\w{3}) (\d{1,2}) (\d{4}) (\d{2}:\d{2}:\d{2}) GMT([+-]\d{2}):(\d{2})/
        );

        console.log('Manual Parse Match:', manualParseMatch);

        if (manualParseMatch) {
          const [, , monthStr, day, year, time, tzH, tzM] = manualParseMatch;
          const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
          const monthIndex = months.indexOf(monthStr);

          if (monthIndex === -1) {
            console.error('Invalid month:', monthStr);
            return null;
          }

          // Convert to ISO 8601 format with timezone
          const isoDate = `${year}-${String(monthIndex + 1).padStart(2, '0')}-${day.padStart(2, '0')}T${time}${tzH}:${tzM}`;
          parsedDate = new Date(isoDate);

          console.log('Parsed Date (Manual):', parsedDate);
        }
      }
    }
  } else {
    parsedDate = new Date(date);
  }

  // Final validity check
  if (isNaN(parsedDate.getTime())) {
    console.error('Invalid date input:', date);
    return null;
  }

  // Ensure the date is not before 1900
  if (parsedDate < new Date('1900-01-01T00:00:00Z')) {
    console.warn('Date before 1900 is not supported:', date);
    return null;
  }

  // Format the date as ISO 8601
  const year = parsedDate.getUTCFullYear();
  const month = String(parsedDate.getUTCMonth() + 1).padStart(2, '0');
  const day = String(parsedDate.getUTCDate()).padStart(2, '0');

  if (includeTime) {
    const hours = String(parsedDate.getUTCHours()).padStart(2, '0');
    const minutes = String(parsedDate.getUTCMinutes()).padStart(2, '0');
    const seconds = String(parsedDate.getUTCSeconds()).padStart(2, '0');
    const milliseconds = String(parsedDate.getUTCMilliseconds()).padStart(3, '0');
    return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}.${milliseconds}Z`;
  }

  return `${year}-${month}-${day}T00:00:00.000Z`;
}

function removeTypename(data) {
  if (Array.isArray(data)) {
    return data.map(removeTypename);
  }
  if (data !== null && typeof data === 'object') {
    const { __typename, ...rest } = data; // Destructure to remove __typename
    return Object.fromEntries(
      Object.entries(rest).map(([key, value]) => [key, removeTypename(value)])
    );
  }
  return data;
}

