  delete updatedData.updatedAt;
  delete updatedData.monthsPassed;

  if (updatedData.actions !== undefined) {
    updatedData.action = updatedData.actions;
    delete updatedData.actions;
  }
  if (updatedData.documents !== undefined) {
    updatedData.document = updatedData.documents;
    delete updatedData.documents;
  }
  if (updatedData.advertisements !== undefined) {
    updatedData.advertisement = updatedData.advertisements;
    delete updatedData.advertisements;
  }

